#include <vector>
#include <algorithm>

class Solution {
public:
    int minRemovals(std::vector<int>& nums, int k) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        int max_kept = 0;

        for (int i = 0; i < n; ++i) {
            long long target = 1LL * nums[i] * k;
            auto it = std::upper_bound(nums.begin(), nums.end(), target);
            int count = std::distance(nums.begin() + i, it);
            max_kept = std::max(max_kept, count);
        }
        return n - max_kept;
    }
};

import java.util.*;

class Solution {
    public int minRemovals(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int maxKept = 0;

        for (int i = 0; i < n; i++) {
            long target = (long) nums[i] * k;
            int low = i, high = n;
            while (low < high) {
                int mid = (low + high) >>> 1;
                if (nums[mid] <= target) {
                    low = mid + 1;
                } else {
                    high = mid;
                }
            }
            maxKept = Math.max(maxKept, low - i);
        }
        return n - maxKept;
    }
}

